fn numpy_not_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // We assume x1.len() == x2.len().
    // Iterate through both vectors simultaneously, compare elements for inequality,
    // and collect the boolean results into a new Vec<bool>.
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a != b)
      .collect()
}

